import{_ as t,o as a,c as o,a4 as d}from"./chunks/framework.DA9C4Pbl.js";const p=JSON.parse('{"title":"Environment (.env)","description":"","frontmatter":{"title":"Environment (.env)","visibility":"public","audience":"operator","tier":"reference","source":"generated","cli":"4.2.1","template":"6.4"},"headers":[],"relativePath":"reference/compose/environment.md","filePath":"reference/compose/environment.md"}'),r={name:"reference/compose/environment.md"};function n(s,e,c,i,h,l){return a(),o("div",null,[...e[0]||(e[0]=[d('<h1 id="environment-env" tabindex="-1">Environment (.env) <a class="header-anchor" href="#environment-env" aria-label="Permalink to “Environment (.env)”">​</a></h1><p>Every key the <code>.env</code> file next to <code>docker-compose.yml</code> can hold: the ones <code>arcsecond setup</code> writes, the ones you fill in, and the ones only the backend reads. Compose reads this file and hands the values to the containers; a container keeps the values it was created with, so after editing it run <code>arcsecond restart</code>.</p><div class="warning custom-block"><p class="custom-block-title custom-block-title-default">WARNING</p><p>A <code>$</code> in a value is interpolated by compose. Quotes, backslashes and <code>#</code> break the parse. Keep values plain.</p></div><table tabindex="0"><thead><tr><th>Key</th><th>Who sets it</th><th>What it is for</th></tr></thead><tbody><tr><td><code>SECRET_KEY</code></td><td>written by <code>arcsecond setup</code></td><td>Django&#39;s secret key: signs sessions and tokens. Generated once; changing it logs everyone out.</td></tr><tr><td><code>AUTH_JWT_SIGNING_KEY</code></td><td>written by <code>arcsecond setup</code></td><td>Signs the access tokens of the web interface and the CLI. Changing it logs everyone out.</td></tr><tr><td><code>AGENT_JWT_SIGNING_KEY</code></td><td>written by <code>arcsecond setup</code></td><td>Signs the tokens of the equipment agents talking to the Control Room.</td></tr><tr><td><code>FIELD_ENCRYPTION_KEY</code></td><td>written by <code>arcsecond setup</code></td><td>Encrypts sensitive fields in the database — external-storage credentials among them. Losing it makes those fields unreadable.</td></tr><tr><td><code>SHARED_DATA_PATH</code></td><td>written by <code>arcsecond setup</code></td><td>The folder on this machine where the installation keeps everything it persists: data files, previews, caches, database backups. Mounted as /data inside the containers. Asked at setup.</td></tr><tr><td><code>POSTGRES_USER</code></td><td>written by <code>arcsecond setup</code></td><td>The database role. Stable across installs.</td></tr><tr><td><code>POSTGRES_PASSWORD</code></td><td>written by <code>arcsecond setup</code></td><td>The role&#39;s password, generated per install. Only read by Postgres on the very first boot; rotate it with <code>arcsecond db set-password</code>, never by editing this line alone.</td></tr><tr><td><code>POSTGRES_DB</code></td><td>written by <code>arcsecond setup</code></td><td>The database name.</td></tr><tr><td><code>GCN_CONSUMER_CLIENT_ID</code></td><td>set by the operator</td><td>NASA GCN client credentials for the optional transient-alerts service. Empty until you paste yours.</td></tr><tr><td><code>GCN_CONSUMER_CLIENT_SECRET</code></td><td>set by the operator</td><td>See GCN_CONSUMER_CLIENT_ID.</td></tr><tr><td><code>HOSTED_FRONTEND_HOST</code></td><td>set by the operator</td><td>The address other computers reach the installation at, port included (e.g. 192.168.1.42:5555). The backend builds invitation and password-reset links from it. Empty means localhost:5555. Set with <code>arcsecond setup --lan-host</code>.</td></tr><tr><td><code>ARCSECOND_OPTIONAL_SERVICES</code></td><td>written by <code>arcsecond setup</code></td><td>The operator&#39;s yes/no answers about optional services (e.g. <code>alerts:yes</code>), so setup does not ask again.</td></tr><tr><td><code>HOSTED_FRONTEND_SCHEME</code></td><td>read by the backend</td><td><code>http</code> (default) or <code>https</code>, when a TLS-terminating reverse proxy of your own sits in front of the installation.</td></tr><tr><td><code>HOSTED_EXTRA_TRUSTED_ORIGINS</code></td><td>read by the backend</td><td>Comma-separated origins, scheme included, to trust besides private-network addresses — a public domain, a Tailscale name. Not needed for a LAN address.</td></tr><tr><td><code>LIVE_IMAGE_PROXY_URL</code></td><td>read by the backend</td><td>Where the backend reaches the live-image proxy for cameras. Default <a href="http://host.docker.internal:8765" target="_blank" rel="noreferrer">http://host.docker.internal:8765</a>; change it only for a proxy on another machine, then <code>arcsecond restart backend</code>.</td></tr><tr><td><code>LOCAL_EMAIL_VERIFICATION_GRACE_HOURS</code></td><td>read by the backend</td><td>How long a new member may use the installation before verifying their email, on an installation with no mail server.</td></tr></tbody></table><h2 id="secret_key" tabindex="-1"><code>SECRET_KEY</code> <a class="header-anchor" href="#secret_key" aria-label="Permalink to “SECRET_KEY”">​</a></h2><p><em>Written by <code>arcsecond setup</code>.</em> Django&#39;s secret key: signs sessions and tokens. Generated once; changing it logs everyone out.</p><h2 id="auth_jwt_signing_key" tabindex="-1"><code>AUTH_JWT_SIGNING_KEY</code> <a class="header-anchor" href="#auth_jwt_signing_key" aria-label="Permalink to “AUTH_JWT_SIGNING_KEY”">​</a></h2><p><em>Written by <code>arcsecond setup</code>.</em> Signs the access tokens of the web interface and the CLI. Changing it logs everyone out.</p><h2 id="agent_jwt_signing_key" tabindex="-1"><code>AGENT_JWT_SIGNING_KEY</code> <a class="header-anchor" href="#agent_jwt_signing_key" aria-label="Permalink to “AGENT_JWT_SIGNING_KEY”">​</a></h2><p><em>Written by <code>arcsecond setup</code>.</em> Signs the tokens of the equipment agents talking to the Control Room.</p><h2 id="field_encryption_key" tabindex="-1"><code>FIELD_ENCRYPTION_KEY</code> <a class="header-anchor" href="#field_encryption_key" aria-label="Permalink to “FIELD_ENCRYPTION_KEY”">​</a></h2><p><em>Written by <code>arcsecond setup</code>.</em> Encrypts sensitive fields in the database — external-storage credentials among them. Losing it makes those fields unreadable.</p><h2 id="shared_data_path" tabindex="-1"><code>SHARED_DATA_PATH</code> <a class="header-anchor" href="#shared_data_path" aria-label="Permalink to “SHARED_DATA_PATH”">​</a></h2><p><em>Written by <code>arcsecond setup</code>.</em> The folder on this machine where the installation keeps everything it persists: data files, previews, caches, database backups. Mounted as /data inside the containers. Asked at setup.</p><h2 id="postgres_user" tabindex="-1"><code>POSTGRES_USER</code> <a class="header-anchor" href="#postgres_user" aria-label="Permalink to “POSTGRES_USER”">​</a></h2><p><em>Written by <code>arcsecond setup</code>.</em> The database role. Stable across installs.</p><h2 id="postgres_password" tabindex="-1"><code>POSTGRES_PASSWORD</code> <a class="header-anchor" href="#postgres_password" aria-label="Permalink to “POSTGRES_PASSWORD”">​</a></h2><p><em>Written by <code>arcsecond setup</code>.</em> The role&#39;s password, generated per install. Only read by Postgres on the very first boot; rotate it with <code>arcsecond db set-password</code>, never by editing this line alone.</p><h2 id="postgres_db" tabindex="-1"><code>POSTGRES_DB</code> <a class="header-anchor" href="#postgres_db" aria-label="Permalink to “POSTGRES_DB”">​</a></h2><p><em>Written by <code>arcsecond setup</code>.</em> The database name.</p><h2 id="gcn_consumer_client_id" tabindex="-1"><code>GCN_CONSUMER_CLIENT_ID</code> <a class="header-anchor" href="#gcn_consumer_client_id" aria-label="Permalink to “GCN_CONSUMER_CLIENT_ID”">​</a></h2><p><em>Set by the operator.</em> NASA GCN client credentials for the optional transient-alerts service. Empty until you paste yours.</p><h2 id="gcn_consumer_client_secret" tabindex="-1"><code>GCN_CONSUMER_CLIENT_SECRET</code> <a class="header-anchor" href="#gcn_consumer_client_secret" aria-label="Permalink to “GCN_CONSUMER_CLIENT_SECRET”">​</a></h2><p><em>Set by the operator.</em> See GCN_CONSUMER_CLIENT_ID.</p><h2 id="hosted_frontend_host" tabindex="-1"><code>HOSTED_FRONTEND_HOST</code> <a class="header-anchor" href="#hosted_frontend_host" aria-label="Permalink to “HOSTED_FRONTEND_HOST”">​</a></h2><p><em>Set by the operator.</em> The address other computers reach the installation at, port included (e.g. 192.168.1.42:5555). The backend builds invitation and password-reset links from it. Empty means localhost:5555. Set with <code>arcsecond setup --lan-host</code>.</p><h2 id="arcsecond_optional_services" tabindex="-1"><code>ARCSECOND_OPTIONAL_SERVICES</code> <a class="header-anchor" href="#arcsecond_optional_services" aria-label="Permalink to “ARCSECOND_OPTIONAL_SERVICES”">​</a></h2><p><em>Written by <code>arcsecond setup</code>.</em> The operator&#39;s yes/no answers about optional services (e.g. <code>alerts:yes</code>), so setup does not ask again.</p><h2 id="hosted_frontend_scheme" tabindex="-1"><code>HOSTED_FRONTEND_SCHEME</code> <a class="header-anchor" href="#hosted_frontend_scheme" aria-label="Permalink to “HOSTED_FRONTEND_SCHEME”">​</a></h2><p><em>Read by the backend.</em> <code>http</code> (default) or <code>https</code>, when a TLS-terminating reverse proxy of your own sits in front of the installation.</p><h2 id="hosted_extra_trusted_origins" tabindex="-1"><code>HOSTED_EXTRA_TRUSTED_ORIGINS</code> <a class="header-anchor" href="#hosted_extra_trusted_origins" aria-label="Permalink to “HOSTED_EXTRA_TRUSTED_ORIGINS”">​</a></h2><p><em>Read by the backend.</em> Comma-separated origins, scheme included, to trust besides private-network addresses — a public domain, a Tailscale name. Not needed for a LAN address.</p><h2 id="live_image_proxy_url" tabindex="-1"><code>LIVE_IMAGE_PROXY_URL</code> <a class="header-anchor" href="#live_image_proxy_url" aria-label="Permalink to “LIVE_IMAGE_PROXY_URL”">​</a></h2><p><em>Read by the backend.</em> Where the backend reaches the live-image proxy for cameras. Default <a href="http://host.docker.internal:8765" target="_blank" rel="noreferrer">http://host.docker.internal:8765</a>; change it only for a proxy on another machine, then <code>arcsecond restart backend</code>.</p><h2 id="local_email_verification_grace_hours" tabindex="-1"><code>LOCAL_EMAIL_VERIFICATION_GRACE_HOURS</code> <a class="header-anchor" href="#local_email_verification_grace_hours" aria-label="Permalink to “LOCAL_EMAIL_VERIFICATION_GRACE_HOURS”">​</a></h2><p><em>Read by the backend.</em> How long a new member may use the installation before verifying their email, on an installation with no mail server.</p>',36)])])}const m=t(r,[["render",n]]);export{p as __pageData,m as default};
